"""Textes du Port, morceau 3 : fiches notions (enfant, grands, limite de l'image, idée fausse), meubles du port et
pages du phare."""
L = ["fr", "en", "es", "de", "it", "pt", "ru", "zh", "ja", "hi", "ar", "bn", "id", "ur"]


def T(*v):
    assert len(v) == 14, v[0]
    return dict(zip(L, v))


K = {
 # ---- fiches
 "port.f.localhost.enfant": T("localhost, c'est ton camp de base : une adresse qui revient toujours chez toi.", "localhost is your base camp: an address that always leads back home.", "localhost es tu campamento base: una dirección que siempre vuelve a casa.", "localhost ist dein Basislager: eine Adresse, die immer zu dir zurückführt.", "localhost è il tuo campo base: un indirizzo che riporta sempre a casa.", "localhost é o teu acampamento base: um endereço que volta sempre a casa.", "localhost — твой базовый лагерь: адрес, который всегда ведёт домой.", "localhost 就是你的大本营：一个总是回到自己家的地址。", "localhost はきみのベースキャンプ。いつも自分のところにもどってくるアドレス。", "localhost तुम्हारा आधार शिविर है: ऐसा पता जो हमेशा घर लौटता है।", "localhost هو معسكرك: عنوان يعود دائمًا إليك.", "localhost তোমার বেস ক্যাম্প: যে ঠিকানা সবসময় তোমার কাছেই ফেরে।", "localhost adalah perkemahan dasarmu: alamat yang selalu kembali ke rumah.", "localhost تمہارا بیس کیمپ ہے: ایسا پتہ جو ہمیشہ گھر لوٹتا ہے۔"),
 "port.f.localhost.grands": T("localhost (127.0.0.1, et ::1 en IPv6) désigne la machine elle-même ; tout le bloc 127.0.0.0/8 reste dans la machine.", "localhost (127.0.0.1, and ::1 in IPv6) means the machine itself; the whole 127.0.0.0/8 block stays inside the machine.", "localhost (127.0.0.1, y ::1 en IPv6) designa la propia máquina; todo el bloque 127.0.0.0/8 se queda dentro.", "localhost (127.0.0.1, in IPv6 ::1) bezeichnet die Maschine selbst; der ganze Block 127.0.0.0/8 bleibt in ihr.", "localhost (127.0.0.1, e ::1 in IPv6) indica la macchina stessa; tutto il blocco 127.0.0.0/8 resta nella macchina.", "localhost (127.0.0.1, e ::1 em IPv6) designa a própria máquina; todo o bloco 127.0.0.0/8 fica lá dentro.", "localhost (127.0.0.1, а в IPv6 ::1) обозначает саму машину; весь блок 127.0.0.0/8 остаётся внутри неё.", "localhost（127.0.0.1，IPv6 中是 ::1）指机器本身；整个 127.0.0.0/8 地址块都留在机器内部。", "localhost（127.0.0.1、IPv6 では ::1）はマシン自身のこと。127.0.0.0/8 のブロック全体がマシンの中にとどまる。", "localhost (127.0.0.1, और IPv6 में ::1) मशीन ख़ुद है; पूरा 127.0.0.0/8 खंड मशीन के भीतर रहता है।", "يشير localhost (127.0.0.1، و ::1 في IPv6) إلى الآلة نفسها؛ وتبقى الكتلة 127.0.0.0/8 كلها داخلها.", "localhost (127.0.0.1, আর IPv6-এ ::1) মানে যন্ত্রটা নিজেই; পুরো 127.0.0.0/8 ব্লক যন্ত্রের ভেতরে থাকে।", "localhost (127.0.0.1, dan ::1 di IPv6) berarti mesin itu sendiri; seluruh blok 127.0.0.0/8 tetap di dalam mesin.", "localhost (127.0.0.1، اور IPv6 میں ::1) خود مشین ہے؛ پورا 127.0.0.0/8 بلاک مشین کے اندر رہتا ہے۔"),
 "port.f.localhost.limite": T("Le camp de base n'est pas un lieu du réseau : un message envoyé à localhost ne passe par aucun câble.", "The base camp is not a place on the network: a message sent to localhost goes through no cable.", "El campamento base no es un lugar de la red: un mensaje enviado a localhost no pasa por ningún cable.", "Das Basislager ist kein Ort im Netz: Eine Nachricht an localhost läuft durch kein Kabel.", "Il campo base non è un luogo della rete: un messaggio inviato a localhost non passa per nessun cavo.", "O acampamento base não é um lugar da rede: uma mensagem enviada para localhost não passa por nenhum cabo.", "Базовый лагерь — не место в сети: сообщение для localhost не идёт ни по какому кабелю.", "大本营并不是网络上的某个地方：发给 localhost 的消息不经过任何电缆。", "ベースキャンプはネットワークの上の場所ではない。localhost に送ったメッセージはどのケーブルも通らない。", "आधार शिविर नेटवर्क की कोई जगह नहीं है: localhost को भेजा संदेश किसी तार से नहीं गुज़रता।", "المعسكر ليس مكانًا في الشبكة: رسالة إلى localhost لا تمر بأي كابل.", "বেস ক্যাম্প নেটওয়ার্কের কোনো জায়গা নয়: localhost-এ পাঠানো বার্তা কোনো তারের ভেতর দিয়ে যায় না।", "Perkemahan dasar bukan tempat di jaringan: pesan ke localhost tidak melewati kabel apa pun.", "بیس کیمپ نیٹ ورک کی کوئی جگہ نہیں: localhost کو بھیجا پیغام کسی تار سے نہیں گزرتا۔"),
 "port.f.localhost.idee": T("« 127.0.0.1 est l'adresse de mon ordinateur sur Internet » : non, chaque machine a sa propre boucle, qui ne sort jamais.", "\"127.0.0.1 is my computer's address on the Internet\": no, every machine has its own loopback, which never leaves it.", "«127.0.0.1 es la dirección de mi ordenador en Internet»: no, cada máquina tiene su propio bucle, que nunca sale.", "„127.0.0.1 ist die Adresse meines Computers im Internet“: Nein, jede Maschine hat ihre eigene Schleife, die nie hinausgeht.", "«127.0.0.1 è l'indirizzo del mio computer su Internet»: no, ogni macchina ha il suo loopback, che non esce mai.", "«127.0.0.1 é o endereço do meu computador na Internet»: não, cada máquina tem o seu loopback, que nunca sai.", "«127.0.0.1 — адрес моего компьютера в Интернете»: нет, у каждой машины своя петля, и она никогда не выходит наружу.", "「127.0.0.1 是我的电脑在互联网上的地址」：不对，每台机器都有自己的回环，它从不出去。", "「127.0.0.1 はインターネットでのぼくのコンピューターの住所」：ちがうよ。どのマシンにも自分のループバックがあって、外には出ない。", "«127.0.0.1 इंटरनेट पर मेरे कंप्यूटर का पता है»: नहीं, हर मशीन का अपना लूपबैक है, जो कभी बाहर नहीं जाता।", "«127.0.0.1 هو عنوان حاسوبي على الإنترنت»: لا، لكل آلة حلقتها الخاصة التي لا تخرج أبدًا.", "«127.0.0.1 ইন্টারনেটে আমার কম্পিউটারের ঠিকানা»: না, প্রতিটি যন্ত্রের নিজের লুপব্যাক আছে, যা কখনও বাইরে যায় না।", "\"127.0.0.1 adalah alamat komputerku di Internet\": bukan, setiap mesin punya loopback sendiri yang tidak pernah keluar.", "«127.0.0.1 انٹرنیٹ پر میرے کمپیوٹر کا پتہ ہے»: نہیں، ہر مشین کا اپنا لوپ بیک ہے جو کبھی باہر نہیں جاتا۔"),
 "port.f.hosts.enfant": T("L'annuaire du port : tu donnes un nom, il te donne le numéro du quai.", "The harbour directory: you give a name, it gives you the dock number.", "El directorio del puerto: das un nombre y te da el número del muelle.", "Das Hafenverzeichnis: Du nennst einen Namen, es gibt dir die Kainummer.", "L'elenco del porto: dai un nome e ti dà il numero della banchina.", "A lista do porto: dás um nome e ela dá-te o número do cais.", "Справочник порта: называешь имя — получаешь номер причала.", "港口地址簿：你给出一个名字，它告诉你码头号。", "港の電話帳：名前を言うと、波止場の番号を教えてくれる。", "बंदरगाह की निर्देशिका: तुम नाम देते हो, वह घाट का नंबर देती है।", "دليل الميناء: تعطيه اسمًا فيعطيك رقم الرصيف.", "বন্দরের ঠিকানার বই: তুমি নাম দাও, সে ঘাটের নম্বর দেয়।", "Buku alamat pelabuhan: kamu memberi nama, ia memberimu nomor dermaga.", "بندرگاہ کی کتاب: تم نام دیتے ہو، وہ گودی کا نمبر دیتی ہے۔"),
 "port.f.hosts.grands": T("La résolution de noms transforme un nom en adresse IP : le fichier /etc/hosts d'abord, puis le DNS.", "Name resolution turns a name into an IP address: the /etc/hosts file first, then DNS.", "La resolución de nombres convierte un nombre en dirección IP: primero el archivo /etc/hosts, luego el DNS.", "Die Namensauflösung macht aus einem Namen eine IP-Adresse: zuerst die Datei /etc/hosts, dann das DNS.", "La risoluzione dei nomi trasforma un nome in indirizzo IP: prima il file /etc/hosts, poi il DNS.", "A resolução de nomes transforma um nome em endereço IP: primeiro o ficheiro /etc/hosts, depois o DNS.", "Разрешение имён превращает имя в IP-адрес: сначала файл /etc/hosts, потом DNS.", "名字解析把名字变成 IP 地址：先查 /etc/hosts 文件，再查 DNS。", "名前解決は名前を IP アドレスに変える。まず /etc/hosts ファイル、次に DNS。", "नाम-समाधान नाम को IP पते में बदलता है: पहले /etc/hosts फ़ाइल, फिर DNS।", "تحويل الأسماء يجعل الاسم عنوان IP: ملف /etc/hosts أولًا ثم DNS.", "নাম-সমাধান একটা নামকে IP ঠিকানায় বদলায়: আগে /etc/hosts ফাইল, তারপর DNS।", "Resolusi nama mengubah nama menjadi alamat IP: berkas /etc/hosts dulu, lalu DNS.", "نام کا حل نام کو IP پتے میں بدلتا ہے: پہلے /etc/hosts فائل، پھر DNS۔"),
 "port.f.hosts.limite": T("Un vrai annuaire ne change pas toutes les heures ; les réponses du DNS, si : elles ont une durée de vie (TTL).", "A real phone book doesn't change every hour; DNS answers do: they have a time to live (TTL).", "Un directorio de verdad no cambia cada hora; las respuestas del DNS sí: tienen una duración de vida (TTL).", "Ein echtes Telefonbuch ändert sich nicht stündlich; DNS-Antworten schon: Sie haben eine Lebensdauer (TTL).", "Un vero elenco non cambia ogni ora; le risposte del DNS sì: hanno un tempo di vita (TTL).", "Uma lista verdadeira não muda a cada hora; as respostas do DNS sim: têm um tempo de vida (TTL).", "Настоящий справочник не меняется каждый час, а ответы DNS — да: у них есть время жизни (TTL).", "真正的电话簿不会每小时都变，DNS 的答案却会：它们有生存时间（TTL）。", "本物の電話帳は 1 時間ごとには変わらないけど、DNS の答えは変わる。寿命（TTL）があるからね。", "असली निर्देशिका हर घंटे नहीं बदलती; DNS के जवाब बदलते हैं: उनकी एक आयु (TTL) होती है।", "الدليل الحقيقي لا يتغير كل ساعة؛ أما أجوبة DNS فتتغير: لها مدة حياة (TTL).", "আসল ঠিকানার বই প্রতি ঘণ্টায় বদলায় না; DNS-এর উত্তর বদলায়: তাদের একটা আয়ু (TTL) আছে।", "Buku alamat sungguhan tidak berubah tiap jam; jawaban DNS berubah: ada masa hidupnya (TTL).", "اصلی پتوں کی کتاب ہر گھنٹے نہیں بدلتی؛ DNS کے جواب بدلتے ہیں: ان کی عمر (TTL) ہوتی ہے۔"),
 "port.f.hosts.idee": T("« Le nom suffit pour se connecter » : non, l'ordinateur a toujours besoin de l'adresse IP.", "\"The name is enough to connect\": no, the computer always needs the IP address.", "«El nombre basta para conectarse»: no, el ordenador siempre necesita la dirección IP.", "„Der Name reicht zum Verbinden“: Nein, der Computer braucht immer die IP-Adresse.", "«Il nome basta per collegarsi»: no, il computer ha sempre bisogno dell'indirizzo IP.", "«O nome chega para ligar»: não, o computador precisa sempre do endereço IP.", "«Чтобы подключиться, хватит имени»: нет, компьютеру всегда нужен IP-адрес.", "「有名字就能连接」：不对，电脑总是需要 IP 地址。", "「名前だけでつながれる」：ちがうよ。コンピューターにはいつも IP アドレスが必要。", "«जुड़ने के लिए नाम काफ़ी है»: नहीं, कंप्यूटर को हमेशा IP पता चाहिए।", "«الاسم يكفي للاتصال»: لا، يحتاج الحاسوب دائمًا إلى عنوان IP.", "«যুক্ত হতে নামই যথেষ্ট»: না, কম্পিউটারের সবসময় IP ঠিকানা লাগে।", "\"Nama saja cukup untuk terhubung\": tidak, komputer selalu butuh alamat IP.", "«جڑنے کے لیے نام کافی ہے»: نہیں، کمپیوٹر کو ہمیشہ IP پتہ چاہیے۔"),
 "port.f.http.enfant": T("curl, c'est le facteur : il porte ta demande et rapporte la lettre avec son enveloppe.", "curl is the postman: it carries your request and brings back the letter with its envelope.", "curl es el cartero: lleva tu petición y trae la carta con su sobre.", "curl ist der Briefträger: Er bringt deine Anfrage hin und den Brief mit Umschlag zurück.", "curl è il postino: porta la tua richiesta e riporta la lettera con la busta.", "O curl é o carteiro: leva o teu pedido e traz a carta com o envelope.", "curl — почтальон: относит твой запрос и приносит письмо с конвертом.", "curl 就是邮差：它送去你的请求，带回信和信封。", "curl は郵便屋さん。きみのお願いを運んで、手紙を封筒ごと持って帰ってくる。", "curl डाकिया है: तुम्हारी माँग ले जाता है और लिफ़ाफ़े सहित चिट्ठी लाता है।", "curl هو ساعي البريد: يحمل طلبك ويعيد الرسالة مع مظروفها.", "curl হলো ডাকপিয়ন: তোমার অনুরোধ নিয়ে যায় আর খামসহ চিঠি ফিরিয়ে আনে।", "curl adalah tukang pos: membawa permintaanmu dan membawa pulang surat beserta amplopnya.", "curl ڈاکیا ہے: تمہاری درخواست لے جاتا ہے اور لفافے سمیت خط لاتا ہے۔"),
 "port.f.http.grands": T("HTTP : une requête (méthode, chemin, en-têtes) et une réponse (code d'état, en-têtes, corps).", "HTTP: a request (method, path, headers) and a response (status code, headers, body).", "HTTP: una petición (método, ruta, cabeceras) y una respuesta (código de estado, cabeceras, cuerpo).", "HTTP: eine Anfrage (Methode, Pfad, Kopfzeilen) und eine Antwort (Statuscode, Kopfzeilen, Körper).", "HTTP: una richiesta (metodo, percorso, intestazioni) e una risposta (codice di stato, intestazioni, corpo).", "HTTP: um pedido (método, caminho, cabeçalhos) e uma resposta (código de estado, cabeçalhos, corpo).", "HTTP: запрос (метод, путь, заголовки) и ответ (код состояния, заголовки, тело).", "HTTP：一个请求（方法、路径、头部）和一个响应（状态码、头部、正文）。", "HTTP：リクエスト（メソッド、パス、ヘッダー）とレスポンス（ステータスコード、ヘッダー、本文）。", "HTTP: एक अनुरोध (विधि, पथ, हेडर) और एक जवाब (स्थिति कोड, हेडर, मुख्य भाग)।", "HTTP: طلب (طريقة، مسار، ترويسات) ورد (رمز الحالة، ترويسات، متن).", "HTTP: একটা অনুরোধ (পদ্ধতি, পথ, হেডার) আর একটা উত্তর (অবস্থা কোড, হেডার, মূল অংশ)।", "HTTP: permintaan (metode, jalur, kepala) dan tanggapan (kode status, kepala, isi).", "HTTP: ایک درخواست (طریقہ، راستہ، ہیڈر) اور ایک جواب (حالت کا کوڈ، ہیڈر، متن)۔"),
 "port.f.http.limite": T("La lettre n'est pas en papier : ce sont des octets, et l'enveloppe (les en-têtes) est du texte aussi.", "The letter isn't paper: it's bytes, and the envelope (the headers) is text too.", "La carta no es de papel: son bytes, y el sobre (las cabeceras) también es texto.", "Der Brief ist nicht aus Papier: Es sind Bytes, und der Umschlag (die Kopfzeilen) ist auch Text.", "La lettera non è di carta: sono byte, e anche la busta (le intestazioni) è testo.", "A carta não é de papel: são octetos, e o envelope (os cabeçalhos) também é texto.", "Письмо не бумажное: это байты, и конверт (заголовки) — тоже текст.", "信不是纸做的：它是字节，信封（头部）也是文字。", "手紙は紙じゃない。バイトの集まりで、封筒（ヘッダー）も文字なんだ。", "चिट्ठी काग़ज़ की नहीं: वह बाइट हैं, और लिफ़ाफ़ा (हेडर) भी टेक्स्ट है।", "الرسالة ليست ورقًا: إنها بايتات، والمظروف (الترويسات) نص أيضًا.", "চিঠিটা কাগজের নয়: সেটা বাইট, আর খামটাও (হেডার) লেখা।", "Suratnya bukan kertas: isinya bita, dan amplopnya (kepala) juga teks.", "خط کاغذ کا نہیں: وہ بائٹس ہیں، اور لفافہ (ہیڈر) بھی متن ہے۔"),
 "port.f.http.idee": T("« 404 veut dire que le site est en panne » : non, le serveur a répondu ; c'est la page qui n'existe pas.", "\"404 means the site is down\": no, the server answered; it's the page that doesn't exist.", "«404 quiere decir que el sitio está caído»: no, el servidor respondió; es la página la que no existe.", "„404 heißt, die Seite ist kaputt“: Nein, der Server hat geantwortet; nur die Seite gibt es nicht.", "«404 vuol dire che il sito è guasto»: no, il server ha risposto; è la pagina a non esistere.", "«404 quer dizer que o sítio está em baixo»: não, o servidor respondeu; é a página que não existe.", "«404 значит, что сайт сломан»: нет, сервер ответил; это страницы нет.", "「404 就是网站坏了」：不对，服务器回答了，只是这个页面不存在。", "「404 はサイトがこわれたということ」：ちがうよ。サーバーは答えた。そのページがないだけ。", "«404 का मतलब साइट बंद है»: नहीं, सर्वर ने जवाब दिया; वह पन्ना ही नहीं है।", "«404 تعني أن الموقع معطل»: لا، أجاب الخادم؛ الصفحة هي غير الموجودة.", "«404 মানে সাইট বন্ধ»: না, সার্ভার উত্তর দিয়েছে; পাতাটাই নেই।", "\"404 berarti situsnya rusak\": tidak, server menjawab; halamannya saja yang tidak ada.", "«404 کا مطلب ہے سائٹ خراب ہے»: نہیں، سرور نے جواب دیا؛ وہ صفحہ ہی موجود نہیں۔"),
 "port.f.ssh_cles.enfant": T("Une clé secrète que tu gardes toujours, et un cadenas que tu peux montrer à tout le monde.", "A secret key you always keep, and a padlock you can show everyone.", "Una llave secreta que guardas siempre y un candado que puedes enseñar a todo el mundo.", "Ein geheimer Schlüssel, den du immer behältst, und ein Schloss, das du allen zeigen darfst.", "Una chiave segreta che tieni sempre e un lucchetto che puoi mostrare a tutti.", "Uma chave secreta que guardas sempre e um cadeado que podes mostrar a toda a gente.", "Секретный ключ, который ты всегда хранишь у себя, и замок, который можно показывать всем.", "一把永远留在你身边的秘密钥匙，和一把可以给所有人看的锁。", "いつも自分が持っているひみつの鍵と、だれに見せてもいい南京錠。", "एक गुप्त चाबी जो हमेशा तुम्हारे पास रहती है, और एक ताला जो सबको दिखा सकते हो।", "مفتاح سري تحتفظ به دائمًا، وقفل يمكنك إظهاره للجميع.", "একটা গোপন চাবি যা সবসময় তোমার কাছে থাকে, আর একটা তালা যা সবাইকে দেখাতে পারো।", "Kunci rahasia yang selalu kamu simpan, dan gembok yang boleh kamu tunjukkan ke semua orang.", "ایک خفیہ چابی جو ہمیشہ تمہارے پاس رہتی ہے، اور ایک تالا جو سب کو دکھا سکتے ہو۔"),
 "port.f.ssh_cles.grands": T("Cryptographie à clé publique : ce que la clé publique permet de vérifier, seule la clé privée peut le produire.", "Public-key cryptography: what the public key can verify, only the private key can produce.", "Criptografía de clave pública: lo que la clave pública permite verificar, solo la privada puede producirlo.", "Public-Key-Kryptografie: Was der öffentliche Schlüssel prüfen kann, kann nur der private erzeugen.", "Crittografia a chiave pubblica: ciò che la chiave pubblica permette di verificare, solo la privata può produrlo.", "Criptografia de chave pública: o que a chave pública permite verificar, só a privada o pode produzir.", "Криптография с открытым ключом: то, что можно проверить открытым ключом, может создать только закрытый.", "公钥密码学：公钥能验证的东西，只有私钥才能生成。", "公開鍵暗号：公開鍵で確かめられるものは、秘密鍵でしかつくれない。", "सार्वजनिक-चाबी क्रिप्टोग्राफ़ी: जिसे सार्वजनिक चाबी जाँच सकती है, उसे सिर्फ़ निजी चाबी बना सकती है।", "تشفير المفتاح العام: ما يتيح المفتاح العام التحقق منه لا ينتجه إلا المفتاح الخاص.", "সর্বজনীন-চাবি ক্রিপ্টোগ্রাফি: সর্বজনীন চাবি যা যাচাই করতে পারে, তা শুধু ব্যক্তিগত চাবিই বানাতে পারে।", "Kriptografi kunci publik: apa yang bisa diverifikasi kunci publik hanya bisa dibuat oleh kunci privat.", "عوامی چابی کی خفیہ نگاری: جسے عوامی چابی جانچ سکتی ہے، اسے صرف نجی چابی بنا سکتی ہے۔"),
 "port.f.ssh_cles.limite": T("Le cadenas peut être copié autant qu'on veut sans danger ; la clé secrète jamais : qui l'a peut se faire passer pour toi.", "The padlock can be copied as much as you like, safely; the secret key never: whoever has it can pretend to be you.", "El candado se puede copiar cuanto se quiera sin peligro; la llave secreta nunca: quien la tenga puede hacerse pasar por ti.", "Das Schloss darf man beliebig oft gefahrlos kopieren, den geheimen Schlüssel nie: Wer ihn hat, kann sich als du ausgeben.", "Il lucchetto si può copiare quanto si vuole senza pericolo; la chiave segreta mai: chi l'ha può fingersi te.", "O cadeado pode ser copiado à vontade sem perigo; a chave secreta nunca: quem a tiver pode fazer-se passar por ti.", "Замок можно безопасно копировать сколько угодно; секретный ключ — никогда: у кого он есть, тот может выдать себя за тебя.", "锁可以随便复制，没有危险；秘密钥匙绝不能复制：谁拿到它，谁就能冒充你。", "南京錠はいくらコピーしても安全。でも秘密鍵はだめ。持っている人がきみになりすませるから。", "ताले की जितनी चाहो नक़ल बिना ख़तरे के बन सकती है; गुप्त चाबी की कभी नहीं: जिसके पास हो वह तुम बनकर दिख सकता है।", "يمكن نسخ القفل بلا خطر كما تشاء؛ أما المفتاح السري فلا أبدًا: من يملكه يستطيع انتحال شخصيتك.", "তালা যত খুশি নকল করা যায়, বিপদ নেই; গোপন চাবি কখনও নয়: যার কাছে থাকে সে তোমার ভান করতে পারে।", "Gembok boleh disalin sebanyak apa pun dengan aman; kunci rahasia jangan pernah: siapa yang memilikinya bisa menyamar jadi kamu.", "تالے کی جتنی چاہو نقل بغیر خطرے کے بن سکتی ہے؛ خفیہ چابی کی کبھی نہیں: جس کے پاس ہو وہ تم بن کر دکھ سکتا ہے۔"),
 "port.f.ssh_cles.idee": T("« La clé publique doit rester secrète » : non, c'est la clé privée qu'on protège.", "\"The public key must stay secret\": no, it's the private key you protect.", "«La clave pública debe ser secreta»: no, la que se protege es la privada.", "„Der öffentliche Schlüssel muss geheim bleiben“: Nein, geschützt wird der private.", "«La chiave pubblica deve restare segreta»: no, è la privata che si protegge.", "«A chave pública tem de ficar secreta»: não, é a privada que se protege.", "«Открытый ключ надо держать в секрете»: нет, защищают закрытый.", "「公钥要保密」：不对，要保护的是私钥。", "「公開鍵はひみつにしなきゃ」：ちがうよ。守るのは秘密鍵。", "«सार्वजनिक चाबी गुप्त रहनी चाहिए»: नहीं, निजी चाबी की रक्षा की जाती है।", "«المفتاح العام يجب أن يبقى سريًا»: لا، المفتاح الخاص هو ما نحميه.", "«সর্বজনীন চাবি গোপন রাখতে হবে»: না, রক্ষা করতে হয় ব্যক্তিগত চাবি।", "\"Kunci publik harus dirahasiakan\": tidak, kunci privatlah yang dilindungi.", "«عوامی چابی خفیہ رہنی چاہیے»: نہیں، نجی چابی کی حفاظت کی جاتی ہے۔"),
 "port.f.serveur.enfant": T("Une lanterne sur ton quai : elle répond à ceux qui viennent frapper.", "A lantern on your dock: it answers whoever comes knocking.", "Una linterna en tu muelle: responde a quien viene a llamar.", "Eine Laterne an deinem Kai: Sie antwortet jedem, der anklopft.", "Una lanterna sulla tua banchina: risponde a chi viene a bussare.", "Uma lanterna no teu cais: responde a quem vem bater.", "Фонарь на твоём причале: он отвечает тем, кто стучится.", "你码头上的一盏灯笼：谁来敲门，它就回答谁。", "きみの波止場のランタン。ノックしに来た人に答える。", "तुम्हारे घाट पर एक लालटेन: जो दस्तक दे, उसे जवाब देती है।", "فانوس على رصيفك: يجيب من يأتي ليطرق.", "তোমার ঘাটে একটা লণ্ঠন: যে কড়া নাড়ে তাকে উত্তর দেয়।", "Lentera di dermagamu: menjawab siapa pun yang datang mengetuk.", "تمہاری گودی پر ایک لالٹین: جو دستک دے اسے جواب دیتی ہے۔"),
 "port.f.serveur.grands": T("Un serveur est un programme qui écoute sur une adresse et un port et répond aux requêtes ; attaché à 127.0.0.1, il est invisible du réseau.", "A server is a program that listens on an address and port and answers requests; bound to 127.0.0.1 it is invisible to the network.", "Un servidor es un programa que escucha en una dirección y un puerto y responde peticiones; atado a 127.0.0.1 es invisible para la red.", "Ein Server ist ein Programm, das auf Adresse und Port lauscht und Anfragen beantwortet; an 127.0.0.1 gebunden ist er fürs Netz unsichtbar.", "Un server è un programma che ascolta su un indirizzo e una porta e risponde alle richieste; legato a 127.0.0.1 è invisibile alla rete.", "Um servidor é um programa que escuta num endereço e numa porta e responde a pedidos; ligado a 127.0.0.1 é invisível para a rede.", "Сервер — программа, которая слушает адрес и порт и отвечает на запросы; привязанный к 127.0.0.1, он невидим для сети.", "服务器是一个在某个地址和端口上监听并回应请求的程序；绑定在 127.0.0.1 上时，网络看不见它。", "サーバーとは、アドレスとポートで待ち受けてリクエストに答えるプログラム。127.0.0.1 に結びつけるとネットワークからは見えない。", "सर्वर एक प्रोग्राम है जो किसी पते और पोर्ट पर सुनता है और अनुरोधों का जवाब देता है; 127.0.0.1 से बँधा हो तो नेटवर्क को नहीं दिखता।", "الخادم برنامج يستمع على عنوان ومنفذ ويجيب الطلبات؛ وإذا رُبط بـ 127.0.0.1 صار خفيًا عن الشبكة.", "সার্ভার এমন প্রোগ্রাম যা কোনো ঠিকানা ও পোর্টে শোনে আর অনুরোধের উত্তর দেয়; 127.0.0.1-এ বাঁধা থাকলে নেটওয়ার্ক তাকে দেখে না।", "Server adalah program yang mendengarkan di sebuah alamat dan port lalu menjawab permintaan; bila terikat ke 127.0.0.1, ia tak terlihat dari jaringan.", "سرور ایک پروگرام ہے جو کسی پتے اور پورٹ پر سنتا ہے اور درخواستوں کا جواب دیتا ہے؛ 127.0.0.1 سے بندھا ہو تو نیٹ ورک کو نظر نہیں آتا۔"),
 "port.f.serveur.limite": T("Un serveur n'est pas forcément une grosse machine : c'est un rôle, et ton ordinateur peut le jouer.", "A server isn't necessarily a big machine: it's a role, and your computer can play it.", "Un servidor no es necesariamente una máquina grande: es un papel, y tu ordenador puede hacerlo.", "Ein Server ist nicht unbedingt eine große Maschine: Es ist eine Rolle, und dein Computer kann sie spielen.", "Un server non è per forza una grossa macchina: è un ruolo, e il tuo computer può interpretarlo.", "Um servidor não é forçosamente uma máquina grande: é um papel, e o teu computador pode desempenhá-lo.", "Сервер — не обязательно большая машина: это роль, и твой компьютер может её играть.", "服务器不一定是大机器：它是一个角色，你的电脑也能扮演。", "サーバーは大きなマシンとはかぎらない。役割のことで、きみのコンピューターにもできる。", "सर्वर ज़रूरी नहीं कि बड़ी मशीन हो: यह एक भूमिका है, और तुम्हारा कंप्यूटर भी निभा सकता है।", "ليس الخادم بالضرورة آلة كبيرة: إنه دور، ويمكن لحاسوبك أن يؤديه.", "সার্ভার মানেই বড় যন্ত্র নয়: এটা একটা ভূমিকা, তোমার কম্পিউটারও পালন করতে পারে।", "Server tidak harus mesin besar: itu sebuah peran, dan komputermu bisa memerankannya.", "سرور ضروری نہیں کہ بڑی مشین ہو: یہ ایک کردار ہے، اور تمہارا کمپیوٹر بھی نبھا سکتا ہے۔"),
 "port.f.serveur.idee": T("« Mon serveur n'est visible que par moi » : seulement s'il écoute sur 127.0.0.1 ; sur 0.0.0.0, tout le réseau local le voit.", "\"Only I can see my server\": only if it listens on 127.0.0.1; on 0.0.0.0 the whole local network sees it.", "«Solo yo veo mi servidor»: solo si escucha en 127.0.0.1; en 0.0.0.0 lo ve toda la red local.", "„Nur ich sehe meinen Server“: Nur wenn er auf 127.0.0.1 lauscht; auf 0.0.0.0 sieht ihn das ganze lokale Netz.", "«Solo io vedo il mio server»: solo se ascolta su 127.0.0.1; su 0.0.0.0 lo vede tutta la rete locale.", "«Só eu vejo o meu servidor»: só se escutar em 127.0.0.1; em 0.0.0.0 toda a rede local o vê.", "«Мой сервер вижу только я»: только если он слушает на 127.0.0.1; на 0.0.0.0 его видит вся локальная сеть.", "「只有我能看到我的服务器」：只有监听在 127.0.0.1 上才是这样；在 0.0.0.0 上，整个局域网都能看到。", "「ぼくのサーバーはぼくにしか見えない」：127.0.0.1 で待っているときだけ。0.0.0.0 ならローカルネットワーク全体から見える。", "«मेरा सर्वर सिर्फ़ मुझे दिखता है»: तभी जब वह 127.0.0.1 पर सुने; 0.0.0.0 पर पूरा स्थानीय नेटवर्क उसे देखता है।", "«لا يرى خادمي غيري»: فقط إن استمع على 127.0.0.1؛ أما على 0.0.0.0 فتراه الشبكة المحلية كلها.", "«আমার সার্ভার শুধু আমি দেখি»: কেবল যদি 127.0.0.1-এ শোনে; 0.0.0.0-তে পুরো স্থানীয় নেটওয়ার্ক দেখে।", "\"Hanya aku yang bisa melihat serverku\": hanya jika ia mendengarkan di 127.0.0.1; di 0.0.0.0 seluruh jaringan lokal melihatnya.", "«میرا سرور صرف مجھے دکھتا ہے»: تبھی جب وہ 127.0.0.1 پر سنے؛ 0.0.0.0 پر پورا مقامی نیٹ ورک اسے دیکھتا ہے۔"),
 "port.f.couches.enfant": T("Une lettre dans une enveloppe, dans un colis, dans un camion.", "A letter in an envelope, in a parcel, in a truck.", "Una carta en un sobre, en un paquete, en un camión.", "Ein Brief in einem Umschlag, in einem Paket, in einem Lastwagen.", "Una lettera in una busta, in un pacco, in un camion.", "Uma carta num envelope, numa encomenda, num camião.", "Письмо в конверте, в посылке, в грузовике.", "一封信装在信封里，信封装在包裹里，包裹装在卡车里。", "手紙が封筒に、封筒が小包に、小包がトラックに。", "चिट्ठी लिफ़ाफ़े में, लिफ़ाफ़ा पार्सल में, पार्सल ट्रक में।", "رسالة في مظروف، في طرد، في شاحنة.", "চিঠি খামে, খাম পার্সেলে, পার্সেল ট্রাকে।", "Surat di dalam amplop, di dalam paket, di dalam truk.", "خط لفافے میں، لفافہ پارسل میں، پارسل ٹرک میں۔"),
 "port.f.couches.grands": T("Le modèle en couches : application, transport, réseau, liaison (les 4 couches de l'Internet ; 7 dans le modèle OSI).", "The layered model: application, transport, network, link (the Internet's 4 layers; 7 in the OSI model).", "El modelo en capas: aplicación, transporte, red, enlace (las 4 capas de Internet; 7 en el modelo OSI).", "Das Schichtenmodell: Anwendung, Transport, Netzwerk, Verbindung (4 Schichten des Internets; 7 im OSI-Modell).", "Il modello a livelli: applicazione, trasporto, rete, collegamento (i 4 livelli di Internet; 7 nel modello OSI).", "O modelo em camadas: aplicação, transporte, rede, ligação (as 4 camadas da Internet; 7 no modelo OSI).", "Модель уровней: приложение, транспорт, сеть, канал (4 уровня Интернета; в модели OSI их 7).", "分层模型：应用层、传输层、网络层、链路层（互联网的 4 层；OSI 模型是 7 层）。", "階層モデル：アプリケーション、トランスポート、ネットワーク、リンク（インターネットの 4 層。OSI モデルでは 7 層）。", "परतों वाला मॉडल: एप्लिकेशन, ट्रांसपोर्ट, नेटवर्क, लिंक (इंटरनेट की 4 परतें; OSI मॉडल में 7)।", "النموذج الطبقي: التطبيق، النقل، الشبكة، الوصلة (طبقات الإنترنت الأربع؛ وسبع في نموذج OSI).", "স্তরের মডেল: অ্যাপ্লিকেশন, ট্রান্সপোর্ট, নেটওয়ার্ক, লিংক (ইন্টারনেটের ৪টি স্তর; OSI মডেলে ৭টি)।", "Model berlapis: aplikasi, transport, jaringan, tautan (4 lapisan Internet; 7 di model OSI).", "تہوں والا ماڈل: ایپلیکیشن، ٹرانسپورٹ، نیٹ ورک، لنک (انٹرنیٹ کی 4 تہیں؛ OSI ماڈل میں 7)۔"),
 "port.f.couches.limite": T("Les couches ne sont pas des objets : ce sont des en-têtes ajoutés autour des données.", "Layers aren't objects: they're headers added around the data.", "Las capas no son objetos: son cabeceras añadidas alrededor de los datos.", "Schichten sind keine Gegenstände: Es sind Kopfzeilen um die Daten herum.", "I livelli non sono oggetti: sono intestazioni aggiunte attorno ai dati.", "As camadas não são objetos: são cabeçalhos acrescentados à volta dos dados.", "Уровни — не предметы: это заголовки, добавленные вокруг данных.", "这些层不是实物：它们是加在数据外面的头部。", "層はものではない。データのまわりにつけたヘッダーのこと。", "परतें वस्तुएँ नहीं हैं: वे डेटा के चारों ओर जोड़े गए हेडर हैं।", "الطبقات ليست أشياء: إنها ترويسات تضاف حول البيانات.", "স্তরগুলো জিনিস নয়: ডেটার চারপাশে জোড়া হেডার।", "Lapisan bukan benda: itu kepala yang ditambahkan di sekeliling data.", "تہیں چیزیں نہیں: یہ ڈیٹا کے گرد لگائے گئے ہیڈر ہیں۔"),
 "port.f.couches.idee": T("« Internet et le Web, c'est pareil » : non, le Web (HTTP) n'est qu'une application qui voyage sur Internet.", "\"The Internet and the Web are the same\": no, the Web (HTTP) is only one application travelling over the Internet.", "«Internet y la web son lo mismo»: no, la web (HTTP) es solo una aplicación que viaja por Internet.", "„Internet und Web sind dasselbe“: Nein, das Web (HTTP) ist nur eine Anwendung, die übers Internet reist.", "«Internet e il Web sono la stessa cosa»: no, il Web (HTTP) è solo un'applicazione che viaggia su Internet.", "«A Internet e a Web são a mesma coisa»: não, a Web (HTTP) é só uma aplicação que viaja pela Internet.", "«Интернет и веб — одно и то же»: нет, веб (HTTP) — лишь одно приложение, которое ездит по Интернету.", "「互联网和网页是一回事」：不对，网页（HTTP）只是在互联网上跑的一种应用。", "「インターネットとウェブは同じ」：ちがうよ。ウェブ（HTTP）はインターネットの上を走るアプリケーションのひとつにすぎない。", "«इंटरनेट और वेब एक ही हैं»: नहीं, वेब (HTTP) इंटरनेट पर चलने वाला बस एक एप्लिकेशन है।", "«الإنترنت والويب شيء واحد»: لا، الويب (HTTP) مجرد تطبيق يسافر عبر الإنترنت.", "«ইন্টারনেট আর ওয়েব একই»: না, ওয়েব (HTTP) ইন্টারনেটের ওপর দিয়ে চলা একটা অ্যাপ্লিকেশন মাত্র।", "\"Internet dan Web itu sama\": tidak, Web (HTTP) hanyalah satu aplikasi yang berjalan di Internet.", "«انٹرنیٹ اور ویب ایک ہی ہیں»: نہیں، ویب (HTTP) انٹرنیٹ پر چلنے والی بس ایک ایپلیکیشن ہے۔"),
 "port.f.ports.enfant": T("Le quai, c'est l'adresse IP ; la porte du hangar, c'est le numéro de port.", "The dock is the IP address; the warehouse door is the port number.", "El muelle es la dirección IP; la puerta del almacén es el número de puerto.", "Der Kai ist die IP-Adresse; die Tür der Halle ist die Portnummer.", "La banchina è l'indirizzo IP; la porta del magazzino è il numero di porta.", "O cais é o endereço IP; a porta do armazém é o número da porta.", "Причал — это IP-адрес; дверь склада — номер порта.", "码头是 IP 地址；仓库的门是端口号。", "波止場は IP アドレス、倉庫のドアはポート番号。", "घाट IP पता है; गोदाम का दरवाज़ा पोर्ट नंबर है।", "الرصيف هو عنوان IP؛ وباب المستودع هو رقم المنفذ.", "ঘাট হলো IP ঠিকানা; গুদামের দরজা হলো পোর্ট নম্বর।", "Dermaga adalah alamat IP; pintu gudang adalah nomor port.", "گودی IP پتہ ہے؛ گودام کا دروازہ پورٹ نمبر ہے۔"),
 "port.f.ports.grands": T("Une socket = une adresse IP + un port (0 à 65535) ; un service écoute sur un port, et ss le montre.", "A socket = an IP address + a port (0 to 65535); a service listens on a port, and ss shows it.", "Un socket = una dirección IP + un puerto (0 a 65535); un servicio escucha en un puerto y ss lo muestra.", "Ein Socket = IP-Adresse + Port (0 bis 65535); ein Dienst lauscht auf einem Port, und ss zeigt ihn.", "Un socket = un indirizzo IP + una porta (da 0 a 65535); un servizio ascolta su una porta e ss lo mostra.", "Um socket = um endereço IP + uma porta (0 a 65535); um serviço escuta numa porta e o ss mostra-o.", "Сокет = IP-адрес + порт (от 0 до 65535); служба слушает порт, и ss это показывает.", "套接字 = IP 地址 + 端口（0 到 65535）；服务在某个端口上监听，ss 可以看到。", "ソケット = IP アドレス + ポート（0〜65535）。サービスはポートで待ち受け、ss がそれを見せる。", "सॉकेट = IP पता + पोर्ट (0 से 65535); कोई सेवा पोर्ट पर सुनती है, और ss उसे दिखाता है।", "المقبس = عنوان IP + منفذ (من 0 إلى 65535)؛ تستمع الخدمة على منفذ ويعرضها ss.", "সকেট = IP ঠিকানা + পোর্ট (০ থেকে ৬৫৫৩৫); একটা সেবা পোর্টে শোনে, আর ss সেটা দেখায়।", "Soket = alamat IP + port (0 sampai 65535); layanan mendengarkan di sebuah port, dan ss menampilkannya.", "ساکٹ = IP پتہ + پورٹ (0 سے 65535)؛ کوئی سروس پورٹ پر سنتی ہے، اور ss اسے دکھاتا ہے۔"),
 "port.f.ports.limite": T("Une machine peut avoir plusieurs adresses (plusieurs quais), et des milliers de portes.", "A machine can have several addresses (several docks), and thousands of doors.", "Una máquina puede tener varias direcciones (varios muelles) y miles de puertas.", "Eine Maschine kann mehrere Adressen (mehrere Kais) und Tausende Türen haben.", "Una macchina può avere più indirizzi (più banchine) e migliaia di porte.", "Uma máquina pode ter vários endereços (vários cais) e milhares de portas.", "У машины может быть несколько адресов (несколько причалов) и тысячи дверей.", "一台机器可以有好几个地址（好几个码头），还有成千上万扇门。", "マシンはアドレス（波止場）をいくつも持てるし、ドアは何千もある。", "एक मशीन के कई पते (कई घाट) और हज़ारों दरवाज़े हो सकते हैं।", "يمكن لآلة أن تملك عدة عناوين (عدة أرصفة) وآلاف الأبواب.", "একটা যন্ত্রের অনেক ঠিকানা (অনেক ঘাট) আর হাজার হাজার দরজা থাকতে পারে।", "Satu mesin bisa punya beberapa alamat (beberapa dermaga) dan ribuan pintu.", "ایک مشین کے کئی پتے (کئی گودیاں) اور ہزاروں دروازے ہو سکتے ہیں۔"),
 "port.f.ports.idee": T("« Un port ouvert, c'est une faille » : non, c'est un service qui écoute ; le danger vient d'un service inutile ou mal protégé.", "\"An open port is a security hole\": no, it's a listening service; the danger comes from a useless or badly protected service.", "«Un puerto abierto es un agujero»: no, es un servicio que escucha; el peligro viene de un servicio inútil o mal protegido.", "„Ein offener Port ist eine Lücke“: Nein, es ist ein lauschender Dienst; Gefahr droht von einem unnötigen oder schlecht geschützten Dienst.", "«Una porta aperta è una falla»: no, è un servizio in ascolto; il pericolo viene da un servizio inutile o mal protetto.", "«Uma porta aberta é uma falha»: não, é um serviço que escuta; o perigo vem de um serviço inútil ou mal protegido.", "«Открытый порт — это дыра»: нет, это слушающая служба; опасна ненужная или плохо защищённая служба.", "「开着的端口就是漏洞」：不对，那是一个在监听的服务；危险来自没用的或保护不好的服务。", "「開いているポートは穴だ」：ちがうよ。待っているサービスがあるだけ。危ないのは、いらないサービスや守りの弱いサービス。", "«खुला पोर्ट एक कमज़ोरी है»: नहीं, वह सुनती हुई एक सेवा है; ख़तरा बेकार या कमज़ोर सुरक्षा वाली सेवा से है।", "«المنفذ المفتوح ثغرة»: لا، إنه خدمة تستمع؛ الخطر يأتي من خدمة لا فائدة منها أو سيئة الحماية.", "«খোলা পোর্ট মানে ফাঁক»: না, সেটা শুনতে থাকা একটা সেবা; বিপদ আসে অপ্রয়োজনীয় বা দুর্বল সুরক্ষার সেবা থেকে।", "\"Port terbuka adalah celah\": tidak, itu layanan yang mendengarkan; bahayanya dari layanan yang tidak perlu atau kurang terlindungi.", "«کھلا پورٹ ایک کمزوری ہے»: نہیں، وہ سنتی ہوئی ایک سروس ہے؛ خطرہ بے کار یا کمزور حفاظت والی سروس سے ہے۔"),
 "port.f.tcp_udp.enfant": T("TCP, c'est la lettre recommandée avec accusé de réception ; UDP, la carte postale.", "TCP is the registered letter with proof of delivery; UDP is the postcard.", "TCP es la carta certificada con acuse de recibo; UDP, la postal.", "TCP ist das Einschreiben mit Rückschein; UDP die Postkarte.", "TCP è la raccomandata con ricevuta di ritorno; UDP la cartolina.", "O TCP é a carta registada com aviso de receção; o UDP, o postal.", "TCP — заказное письмо с уведомлением о вручении; UDP — открытка.", "TCP 是带回执的挂号信；UDP 是明信片。", "TCP は配達証明つきの書留、UDP はハガキ。", "TCP पावती वाली रजिस्टर्ड चिट्ठी है; UDP पोस्टकार्ड।", "TCP رسالة مسجّلة بإشعار استلام؛ و UDP بطاقة بريدية.", "TCP প্রাপ্তিস্বীকারসহ রেজিস্ট্রি চিঠি; UDP পোস্টকার্ড।", "TCP adalah surat tercatat dengan tanda terima; UDP adalah kartu pos.", "TCP رسید والا رجسٹرڈ خط ہے؛ UDP پوسٹ کارڈ۔"),
 "port.f.tcp_udp.grands": T("TCP : connexion, accusés de réception, ordre, retransmission. UDP : datagrammes indépendants, sans garantie.", "TCP: connection, acknowledgements, ordering, retransmission. UDP: independent datagrams, no guarantee.", "TCP: conexión, acuses de recibo, orden, retransmisión. UDP: datagramas independientes, sin garantía.", "TCP: Verbindung, Bestätigungen, Reihenfolge, Neuübertragung. UDP: unabhängige Datagramme, ohne Garantie.", "TCP: connessione, ricevute, ordine, ritrasmissione. UDP: datagrammi indipendenti, senza garanzia.", "TCP: ligação, avisos de receção, ordem, retransmissão. UDP: datagramas independentes, sem garantia.", "TCP: соединение, подтверждения, порядок, повторная передача. UDP: независимые датаграммы без гарантий.", "TCP：连接、确认、顺序、重传。UDP：彼此独立的数据报，没有保证。", "TCP：接続、受け取りの返事、順番、再送。UDP：ばらばらのデータグラムで、保証なし。", "TCP: कनेक्शन, पावती, क्रम, दोबारा भेजना। UDP: स्वतंत्र डेटाग्राम, कोई गारंटी नहीं।", "TCP: اتصال، إشعارات استلام، ترتيب، إعادة إرسال. UDP: وحدات بيانات مستقلة دون ضمان.", "TCP: সংযোগ, প্রাপ্তিস্বীকার, ক্রম, পুনঃপ্রেরণ। UDP: স্বাধীন ডেটাগ্রাম, কোনো নিশ্চয়তা নেই।", "TCP: koneksi, tanda terima, urutan, pengiriman ulang. UDP: datagram terpisah, tanpa jaminan.", "TCP: کنکشن، رسیدیں، ترتیب، دوبارہ بھیجنا۔ UDP: الگ الگ ڈیٹاگرام، کوئی ضمانت نہیں۔"),
 "port.f.tcp_udp.limite": T("« Perdu » ne veut pas dire « volé » : un paquet perdu a été jeté, par exemple par un routeur trop chargé.", "\"Lost\" doesn't mean \"stolen\": a lost packet was dropped, for example by an overloaded router.", "«Perdido» no quiere decir «robado»: un paquete perdido fue descartado, por ejemplo por un router saturado.", "„Verloren“ heißt nicht „gestohlen“: Ein verlorenes Paket wurde verworfen, etwa von einem überlasteten Router.", "«Perso» non vuol dire «rubato»: un pacchetto perso è stato scartato, per esempio da un router sovraccarico.", "«Perdido» não quer dizer «roubado»: um pacote perdido foi descartado, por exemplo por um router sobrecarregado.", "«Потерян» не значит «украден»: потерянный пакет выбросили, например, перегруженным маршрутизатором.", "「丢失」不等于「被偷」：丢失的数据包是被丢弃了，比如被太忙的路由器丢掉。", "「なくなった」は「ぬすまれた」ではない。なくなったパケットは、たとえば混みすぎたルーターに捨てられたんだ。", "«खोया» का मतलब «चोरी» नहीं: खोया पैकेट फेंका गया, जैसे किसी ज़्यादा भरे राउटर ने।", "«ضائع» لا تعني «مسروق»: الحزمة الضائعة رُميت، مثلًا من موجّه مزدحم.", "«হারানো» মানে «চুরি» নয়: হারানো প্যাকেট ফেলে দেওয়া হয়েছে, যেমন ভিড়ে ঠাসা কোনো রাউটারে।", "\"Hilang\" bukan berarti \"dicuri\": paket yang hilang dibuang, misalnya oleh router yang terlalu sibuk.", "«کھویا» کا مطلب «چوری» نہیں: کھویا پیکٹ پھینکا گیا، جیسے کسی زیادہ بھرے راؤٹر نے۔"),
 "port.f.tcp_udp.idee": T("« UDP, c'est moins bien » : non, on le choisit exprès quand la vitesse compte plus (jeux, vidéo, DNS).", "\"UDP is worse\": no, it's chosen on purpose when speed matters more (games, video, DNS).", "«UDP es peor»: no, se elige a propósito cuando la velocidad importa más (juegos, vídeo, DNS).", "„UDP ist schlechter“: Nein, man wählt es absichtlich, wenn Tempo wichtiger ist (Spiele, Video, DNS).", "«UDP è peggio»: no, si sceglie apposta quando conta di più la velocità (giochi, video, DNS).", "«O UDP é pior»: não, escolhe-se de propósito quando a velocidade conta mais (jogos, vídeo, DNS).", "«UDP хуже»: нет, его выбирают специально, когда скорость важнее (игры, видео, DNS).", "「UDP 比较差」：不对，在速度更重要时（游戏、视频、DNS）就是故意选它。", "「UDP はおとっている」：ちがうよ。速さが大事なとき（ゲーム、動画、DNS）にわざと選ぶんだ。", "«UDP कमतर है»: नहीं, जब गति ज़्यादा ज़रूरी हो (खेल, वीडियो, DNS) तो उसे जानबूझकर चुनते हैं।", "«UDP أسوأ»: لا، يُختار عمدًا حين تكون السرعة أهم (الألعاب، الفيديو، DNS).", "«UDP খারাপ»: না, গতি যখন বেশি জরুরি (খেলা, ভিডিও, DNS) তখন ইচ্ছে করেই বেছে নেওয়া হয়।", "\"UDP itu lebih buruk\": tidak, ia sengaja dipilih saat kecepatan lebih penting (gim, video, DNS).", "«UDP کمتر ہے»: نہیں، جب رفتار زیادہ اہم ہو (کھیل، ویڈیو، DNS) تو اسے جان بوجھ کر چنتے ہیں۔"),
 "port.f.routage.enfant": T("Les phares se passent la lumière de proche en proche jusqu'à la bonne machine.", "The lighthouses pass the light along, one to the next, up to the right machine.", "Los faros se pasan la luz de uno en uno hasta la máquina correcta.", "Die Leuchttürme geben das Licht von einem zum nächsten weiter bis zur richtigen Maschine.", "I fari si passano la luce uno dopo l'altro fino alla macchina giusta.", "Os faróis passam a luz de um para o outro até à máquina certa.", "Маяки передают свет от одного к другому до нужной машины.", "灯塔一座接一座地传递光，直到正确的机器。", "灯台が光をつぎつぎにわたして、正しいマシンまで届ける。", "प्रकाशस्तंभ एक से दूसरे को रोशनी देते हुए सही मशीन तक पहुँचाते हैं।", "تمرّر المنارات الضوء من واحدة إلى الأخرى حتى الآلة الصحيحة.", "বাতিঘরেরা একের পর এক আলো দিয়ে ঠিক যন্ত্র পর্যন্ত পৌঁছে দেয়।", "Mercusuar meneruskan cahaya dari satu ke yang lain sampai mesin yang tepat.", "لائٹ ہاؤس ایک سے دوسرے کو روشنی دیتے ہوئے صحیح مشین تک پہنچاتے ہیں۔"),
 "port.f.routage.grands": T("Le routage : chaque routeur choisit le prochain saut d'après sa table ; le TTL limite le nombre de sauts.", "Routing: each router picks the next hop from its table; the TTL limits the number of hops.", "El enrutamiento: cada router elige el siguiente salto según su tabla; el TTL limita el número de saltos.", "Routing: Jeder Router wählt den nächsten Sprung nach seiner Tabelle; die TTL begrenzt die Zahl der Sprünge.", "L'instradamento: ogni router sceglie il salto successivo dalla sua tabella; il TTL limita il numero di salti.", "O encaminhamento: cada router escolhe o próximo salto segundo a sua tabela; o TTL limita o número de saltos.", "Маршрутизация: каждый маршрутизатор выбирает следующий прыжок по своей таблице; TTL ограничивает число прыжков.", "路由：每个路由器按自己的表选择下一跳；TTL 限制跳数。", "ルーティング：ルーターはそれぞれテーブルで次のジャンプを選ぶ。TTL がジャンプの数を制限する。", "रूटिंग: हर राउटर अपनी टेबल से अगली छलाँग चुनता है; TTL छलाँगों की संख्या सीमित करता है।", "التوجيه: يختار كل موجّه القفزة التالية من جدوله؛ ويحدّ TTL عدد القفزات.", "রাউটিং: প্রতিটি রাউটার নিজের টেবিল দেখে পরের লাফ বেছে নেয়; TTL লাফের সংখ্যা সীমিত করে।", "Perutean: setiap router memilih lompatan berikutnya dari tabelnya; TTL membatasi jumlah lompatan.", "روٹنگ: ہر راؤٹر اپنی ٹیبل سے اگلی چھلانگ چنتا ہے؛ TTL چھلانگوں کی تعداد محدود کرتا ہے۔"),
 "port.f.routage.limite": T("Le chemin peut changer à chaque paquet, et l'aller et le retour peuvent passer par des chemins différents.", "The path can change for each packet, and the way there and back can take different paths.", "El camino puede cambiar en cada paquete, y la ida y la vuelta pueden ir por caminos distintos.", "Der Weg kann sich bei jedem Paket ändern, und Hin- und Rückweg können verschieden sein.", "Il percorso può cambiare a ogni pacchetto, e andata e ritorno possono passare per strade diverse.", "O caminho pode mudar em cada pacote, e a ida e a volta podem seguir caminhos diferentes.", "Путь может меняться для каждого пакета, а туда и обратно можно идти разными дорогами.", "每个数据包的路径都可能不同，去和回也可能走不同的路。", "道はパケットごとに変わることがあるし、行きと帰りで道がちがうこともある。", "हर पैकेट का रास्ता बदल सकता है, और जाना-आना अलग रास्तों से हो सकता है।", "قد يتغير الطريق مع كل حزمة، وقد يسلك الذهاب والإياب طريقين مختلفين.", "প্রতিটি প্যাকেটের পথ বদলাতে পারে, আর যাওয়া-আসা আলাদা পথে হতে পারে।", "Jalurnya bisa berubah untuk setiap paket, dan pergi serta pulang bisa lewat jalur berbeda.", "ہر پیکٹ کا راستہ بدل سکتا ہے، اور جانا آنا الگ راستوں سے ہو سکتا ہے۔"),
 "port.f.routage.idee": T("« Un message va tout droit d'un ordinateur à l'autre » : non, il saute de routeur en routeur.", "\"A message goes straight from one computer to the other\": no, it hops from router to router.", "«Un mensaje va directo de un ordenador a otro»: no, salta de router en router.", "„Eine Nachricht geht direkt von einem Computer zum anderen“: Nein, sie springt von Router zu Router.", "«Un messaggio va dritto da un computer all'altro»: no, salta da router a router.", "«Uma mensagem vai direta de um computador ao outro»: não, salta de router em router.", "«Сообщение идёт напрямую от компьютера к компьютеру»: нет, оно прыгает от маршрутизатора к маршрутизатору.", "「消息从一台电脑直接到另一台」：不对，它在路由器之间一跳一跳地走。", "「メッセージはコンピューターからコンピューターへまっすぐ行く」：ちがうよ。ルーターからルーターへジャンプしていく。", "«संदेश एक कंप्यूटर से दूसरे तक सीधा जाता है»: नहीं, वह राउटर से राउटर कूदता है।", "«الرسالة تذهب مباشرة من حاسوب إلى آخر»: لا، إنها تقفز من موجّه إلى موجّه.", "«বার্তা সোজা এক কম্পিউটার থেকে আরেকটায় যায়»: না, সে রাউটার থেকে রাউটারে লাফায়।", "\"Pesan langsung dari satu komputer ke komputer lain\": tidak, ia melompat dari router ke router.", "«پیغام سیدھا ایک کمپیوٹر سے دوسرے تک جاتا ہے»: نہیں، وہ راؤٹر سے راؤٹر کودتا ہے۔"),
 "port.f.box_nat.enfant": T("La box est le gardien de l'immeuble : elle donne un numéro à chaque appareil et trie le courrier.", "The home router is the building caretaker: it gives each device a number and sorts the mail.", "El router de casa es el conserje: da un número a cada aparato y reparte el correo.", "Der Router ist der Hausmeister: Er gibt jedem Gerät eine Nummer und sortiert die Post.", "Il router di casa è il portinaio: dà un numero a ogni dispositivo e smista la posta.", "O router de casa é o porteiro: dá um número a cada aparelho e separa o correio.", "Домашний роутер — консьерж дома: он даёт номер каждому устройству и сортирует почту.", "家里的路由器就是大楼管理员：它给每台设备一个号码，还负责分拣信件。", "家のルーターはマンションの管理人さん。機械ごとに番号をつけて、郵便を仕分ける。", "घर का राउटर इमारत का चौकीदार है: हर उपकरण को नंबर देता है और डाक छाँटता है।", "موجّه البيت حارس العمارة: يعطي كل جهاز رقمًا ويفرز البريد.", "বাড়ির রাউটার বাড়ির দারোয়ান: প্রতিটি যন্ত্রকে নম্বর দেয় আর চিঠি বাছাই করে।", "Router rumah adalah penjaga gedung: memberi nomor setiap perangkat dan memilah surat.", "گھر کا راؤٹر عمارت کا چوکیدار ہے: ہر آلے کو نمبر دیتا ہے اور ڈاک چھانٹتا ہے۔"),
 "port.f.box_nat.grands": T("La box fait passerelle, serveur DHCP (adresses privées) et NAT (une seule adresse publique pour toute la maison).", "The home router acts as gateway, DHCP server (private addresses) and NAT (a single public address for the whole home).", "El router hace de pasarela, servidor DHCP (direcciones privadas) y NAT (una sola dirección pública para toda la casa).", "Der Router ist Gateway, DHCP-Server (private Adressen) und NAT (eine einzige öffentliche Adresse fürs ganze Zuhause).", "Il router fa da gateway, server DHCP (indirizzi privati) e NAT (un solo indirizzo pubblico per tutta la casa).", "O router faz de porta de ligação, servidor DHCP (endereços privados) e NAT (um só endereço público para a casa toda).", "Роутер — это шлюз, сервер DHCP (частные адреса) и NAT (один публичный адрес на весь дом).", "路由器同时是网关、DHCP 服务器（私有地址）和 NAT（全家只用一个公网地址）。", "家のルーターは、ゲートウェイ、DHCP サーバー（プライベートアドレス）、NAT（家じゅうでひとつのパブリックアドレス）を兼ねる。", "राउटर गेटवे, DHCP सर्वर (निजी पते) और NAT (पूरे घर के लिए एक ही सार्वजनिक पता) का काम करता है।", "يعمل الموجّه بوابةً وخادم DHCP (عناوين خاصة) و NAT (عنوان عام واحد للبيت كله).", "রাউটার গেটওয়ে, DHCP সার্ভার (ব্যক্তিগত ঠিকানা) আর NAT (পুরো বাড়ির জন্য একটাই সর্বজনীন ঠিকানা) হিসেবে কাজ করে।", "Router berperan sebagai gateway, server DHCP (alamat privat), dan NAT (satu alamat publik untuk seluruh rumah).", "راؤٹر گیٹ وے، DHCP سرور (نجی پتے) اور NAT (پورے گھر کے لیے ایک ہی عوامی پتہ) کا کام کرتا ہے۔"),
 "port.f.box_nat.limite": T("Le Wi-Fi n'est pas « Internet » : c'est seulement le dernier mètre entre ton appareil et la box.", "Wi-Fi isn't \"the Internet\": it's only the last metre between your device and the router.", "El wifi no es «Internet»: es solo el último metro entre tu aparato y el router.", "WLAN ist nicht „das Internet“: Es ist nur der letzte Meter zwischen deinem Gerät und dem Router.", "Il Wi-Fi non è «Internet»: è solo l'ultimo metro tra il tuo dispositivo e il router.", "O Wi-Fi não é «a Internet»: é só o último metro entre o teu aparelho e o router.", "Wi-Fi — не «Интернет»: это только последний метр между твоим устройством и роутером.", "Wi-Fi 不是「互联网」：它只是你的设备和路由器之间的最后一米。", "Wi-Fi は「インターネット」ではない。きみの機械とルーターのあいだの、最後の 1 メートルだけ。", "Wi-Fi «इंटरनेट» नहीं है: यह बस तुम्हारे उपकरण और राउटर के बीच का आख़िरी मीटर है।", "الواي فاي ليس «الإنترنت»: إنه فقط المتر الأخير بين جهازك والموجّه.", "Wi-Fi «ইন্টারনেট» নয়: এটা শুধু তোমার যন্ত্র আর রাউটারের মাঝের শেষ এক মিটার।", "Wi-Fi bukan \"Internet\": itu hanya satu meter terakhir antara perangkatmu dan router.", "Wi-Fi «انٹرنیٹ» نہیں: یہ بس تمہارے آلے اور راؤٹر کے بیچ کا آخری میٹر ہے۔"),
 "port.f.box_nat.idee": T("« Mon adresse 192.168… est mon adresse sur Internet » : non, Internet voit l'adresse publique de la box.", "\"My 192.168… address is my address on the Internet\": no, the Internet sees the router's public address.", "«Mi dirección 192.168… es mi dirección en Internet»: no, Internet ve la dirección pública del router.", "„Meine Adresse 192.168… ist meine Adresse im Internet“: Nein, das Internet sieht die öffentliche Adresse des Routers.", "«Il mio indirizzo 192.168… è il mio indirizzo su Internet»: no, Internet vede l'indirizzo pubblico del router.", "«O meu endereço 192.168… é o meu endereço na Internet»: não, a Internet vê o endereço público do router.", "«Мой адрес 192.168… — мой адрес в Интернете»: нет, Интернет видит публичный адрес роутера.", "「我的 192.168… 地址就是我在互联网上的地址」：不对，互联网看到的是路由器的公网地址。", "「ぼくの 192.168… のアドレスがインターネットでの住所」：ちがうよ。インターネットから見えるのはルーターのパブリックアドレス。", "«मेरा 192.168… वाला पता इंटरनेट पर मेरा पता है»: नहीं, इंटरनेट राउटर का सार्वजनिक पता देखता है।", "«عنواني 192.168… هو عنواني على الإنترنت»: لا، الإنترنت يرى العنوان العام للموجّه.", "«আমার 192.168… ঠিকানাই ইন্টারনেটে আমার ঠিকানা»: না, ইন্টারনেট রাউটারের সর্বজনীন ঠিকানা দেখে।", "\"Alamat 192.168… ku adalah alamatku di Internet\": tidak, Internet melihat alamat publik router.", "«میرا 192.168… والا پتہ انٹرنیٹ پر میرا پتہ ہے»: نہیں، انٹرنیٹ راؤٹر کا عوامی پتہ دیکھتا ہے۔"),
 "port.f.tls.enfant": T("L'enveloppe scellée à la cire, avec un sceau vérifié par le notaire.", "The envelope sealed with wax, with a seal checked by the notary.", "El sobre sellado con lacre, con un sello verificado por el notario.", "Der mit Wachs versiegelte Umschlag, mit einem vom Notar geprüften Siegel.", "La busta sigillata con la ceralacca, con un sigillo verificato dal notaio.", "O envelope selado a lacre, com um selo verificado pelo notário.", "Конверт, запечатанный сургучом, с печатью, проверенной нотариусом.", "用火漆封好的信封，封印经过公证人核实。", "ろうで封をした封筒。封印は公証人が確かめたもの。", "मोम से मुहरबंद लिफ़ाफ़ा, जिसकी मुहर नोटरी ने जाँची।", "المظروف المختوم بالشمع، بختم تحقق منه الموثّق.", "গালা দিয়ে সিল করা খাম, নোটারির যাচাই করা সিলমোহরসহ।", "Amplop bersegel lilin, dengan segel yang diperiksa notaris.", "لاکھ سے مہر بند لفافہ، جس کی مہر نوٹری نے جانچی۔"),
 "port.f.tls.grands": T("HTTPS = HTTP dans TLS : chiffrement du trajet et certificat signé par une autorité, au nom du site.", "HTTPS = HTTP inside TLS: the trip is encrypted and the certificate is signed by an authority, in the site's name.", "HTTPS = HTTP dentro de TLS: cifrado del trayecto y certificado firmado por una autoridad, a nombre del sitio.", "HTTPS = HTTP in TLS: verschlüsselter Weg und ein von einer Stelle signiertes Zertifikat auf den Namen der Seite.", "HTTPS = HTTP dentro TLS: cifratura del tragitto e certificato firmato da un'autorità, a nome del sito.", "HTTPS = HTTP dentro de TLS: cifra do trajeto e certificado assinado por uma autoridade, em nome do sítio.", "HTTPS = HTTP внутри TLS: шифрование пути и сертификат, подписанный центром, на имя сайта.", "HTTPS = 包在 TLS 里的 HTTP：传输加密，证书由机构签发，写的是网站的名字。", "HTTPS = TLS の中の HTTP。道のりは暗号化され、証明書は認証局がサイトの名前でサインしたもの。", "HTTPS = TLS के भीतर HTTP: रास्ते का एन्क्रिप्शन और साइट के नाम पर प्राधिकरण से हस्ताक्षरित प्रमाणपत्र।", "HTTPS = ‏HTTP داخل TLS: تشفير الطريق وشهادة موقّعة من جهة باسم الموقع.", "HTTPS = TLS-এর ভেতরে HTTP: পথের এনক্রিপশন আর সাইটের নামে কর্তৃপক্ষের সই করা সার্টিফিকেট।", "HTTPS = HTTP di dalam TLS: perjalanan dienkripsi dan sertifikat ditandatangani otoritas atas nama situs.", "HTTPS = TLS کے اندر HTTP: راستے کی خفیہ کاری اور سائٹ کے نام پر ادارے کا دستخط شدہ سرٹیفکیٹ۔"),
 "port.f.tls.limite": T("Le cadenas prouve à QUI tu parles, pas que le site est honnête.", "The padlock proves WHO you're talking to, not that the site is honest.", "El candado prueba con QUIÉN hablas, no que el sitio sea honrado.", "Das Schloss beweist, mit WEM du sprichst, nicht dass die Seite ehrlich ist.", "Il lucchetto prova con CHI parli, non che il sito sia onesto.", "O cadeado prova com QUEM falas, não que o sítio seja honesto.", "Замок доказывает, С КЕМ ты говоришь, но не то, что сайт честный.", "小锁证明的是你在和「谁」说话，并不证明网站诚实。", "南京錠は「だれと」話しているかを証明する。サイトが正直かどうかではない。", "ताला साबित करता है कि तुम «किससे» बात कर रहे हो, यह नहीं कि साइट ईमानदार है।", "يثبت القفل «مع من» تتحدث، لا أن الموقع نزيه.", "তালা প্রমাণ করে তুমি «কার» সঙ্গে কথা বলছ, সাইট সৎ কিনা নয়।", "Gembok membuktikan dengan SIAPA kamu berbicara, bukan bahwa situsnya jujur.", "تالا ثابت کرتا ہے کہ تم «کس سے» بات کر رہے ہو، یہ نہیں کہ سائٹ ایماندار ہے۔"),
 "port.f.tls.idee": T("« Un site avec un cadenas est forcément sûr » : non, un site trompeur peut aussi avoir un vrai certificat.", "\"A site with a padlock is always safe\": no, a deceptive site can have a real certificate too.", "«Un sitio con candado siempre es seguro»: no, un sitio engañoso también puede tener un certificado real.", "„Eine Seite mit Schloss ist immer sicher“: Nein, auch eine betrügerische Seite kann ein echtes Zertifikat haben.", "«Un sito con il lucchetto è per forza sicuro»: no, anche un sito ingannevole può avere un vero certificato.", "«Um sítio com cadeado é forçosamente seguro»: não, um sítio enganador também pode ter um certificado verdadeiro.", "«Сайт с замком обязательно безопасен»: нет, у обманного сайта тоже может быть настоящий сертификат.", "「有小锁的网站一定安全」：不对，骗人的网站也可能有真证书。", "「南京錠があるサイトはぜったい安全」：ちがうよ。だますサイトでも本物の証明書を持てる。", "«ताले वाली साइट हमेशा सुरक्षित है»: नहीं, धोखेबाज़ साइट के पास भी असली प्रमाणपत्र हो सकता है।", "«الموقع ذو القفل آمن حتمًا»: لا، قد يملك موقع مخادع شهادة حقيقية أيضًا.", "«তালাওয়ালা সাইট নিশ্চয়ই নিরাপদ»: না, প্রতারক সাইটেরও আসল সার্টিফিকেট থাকতে পারে।", "\"Situs bergembok pasti aman\": tidak, situs penipu juga bisa punya sertifikat asli.", "«تالے والی سائٹ ضرور محفوظ ہے»: نہیں، دھوکے باز سائٹ کے پاس بھی اصلی سرٹیفکیٹ ہو سکتا ہے۔"),
}
